#!/usr/bin/env python3
"""Update renewal_playbook.hwpx using renewal_update.json and followups.csv.

Contract highlights:
- HWPX is a ZIP; editable body text is under Contents/*.xml.
- Replace old field values with new values from renewal_update.json.
- Replace follow-up paragraphs using followups.csv (sorted by sequence).
- For every <hp:p> we modify, remove layout-cache elements like lineSegArray/lineSeg/linesegarray/lineseg.
- Preserve appendix sentence exactly: "이 부록 문단은 그대로 유지해야 합니다."

Produces: /root/renewal_playbook_updated.hwpx
"""

from __future__ import annotations

import copy
import csv
import json
import re
import shutil
import zipfile
from dataclasses import dataclass
from pathlib import Path


HWPX_IN = Path("/root/renewal_playbook.hwpx")
HWPX_OUT = Path("/root/renewal_playbook_updated.hwpx")
UPDATE_JSON = Path("/root/renewal_update.json")
FOLLOWUPS_CSV = Path("/root/followups.csv")

HP_NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"
NS = {"hp": HP_NS}

APPENDIX_SENTENCE = "이 부록 문단은 그대로 유지해야 합니다."


def _try_import_lxml():
    try:
        from lxml import etree  # type: ignore

        return etree
    except Exception:
        return None


ETREE = _try_import_lxml()


def localname(tag: str) -> str:
    if tag is None:
        return ""
    if "}" in tag:
        return tag.split("}", 1)[1]
    return tag


def paragraph_full_text(p_elem) -> str:
    # Concatenate all text inside <hp:t> descendants.
    parts = []
    for t in p_elem.findall(".//hp:t", namespaces=NS):
        if t.text:
            parts.append(t.text)
    return "".join(parts)


def build_parent_map(root):
    parent = {}
    for p in root.iter():
        for c in list(p):
            parent[c] = p
    return parent


def find_ancestor_p(elem, parent_map):
    cur = elem
    while cur is not None:
        if localname(getattr(cur, "tag", "")) == "p" and ("}" + localname(cur.tag) if "}" in cur.tag else cur.tag).endswith("p"):
            # localname check is enough; keep it simple
            return cur
        cur = parent_map.get(cur)
    return None


def remove_layout_cache_from_paragraph(p_elem, parent_map) -> int:
    """Remove layout-cache elements from within a paragraph.

    Returns count removed.
    """
    cache_names = {"linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg"}
    # include camelCase variants via .lower() check
    removed = 0

    # We need to remove descendants; iterate over a snapshot list.
    descendants = list(p_elem.iter())
    for d in descendants:
        if d is p_elem:
            continue
        ln = localname(getattr(d, "tag", "")).lower()
        if ln in {"linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg"}:
            pass
        if ln in {"linesegarray", "lineseg", "linesegarray", "lineseg"} or ln in {"linesegarray", "lineseg"}:
            par = parent_map.get(d)
            if par is not None:
                par.remove(d)
                removed += 1

    return removed


def ensure_single_text_run(p_elem):
    """Ensure paragraph has at least one hp:run/hp:t and return that hp:t."""
    runs = p_elem.findall("hp:run", namespaces=NS)
    if runs:
        # Find first <hp:t> inside the first run.
        t = runs[0].find("hp:t", namespaces=NS)
        if t is not None:
            return t
        # If run exists but no hp:t, create one.
        t = ETREE.Element(f"{{{HP_NS}}}t") if ETREE else __import__("xml.etree.ElementTree").Element(f"{{{HP_NS}}}t")
        runs[0].append(t)
        return t

    # Create run + t
    run = ETREE.Element(f"{{{HP_NS}}}run") if ETREE else __import__("xml.etree.ElementTree").Element(f"{{{HP_NS}}}run")
    t = ETREE.Element(f"{{{HP_NS}}}t") if ETREE else __import__("xml.etree.ElementTree").Element(f"{{{HP_NS}}}t")
    run.append(t)
    p_elem.insert(0, run)
    return t


def rewrite_paragraph_text(p_elem, new_text: str):
    """Rewrite paragraph's visible text to exactly new_text by keeping the first run and removing other runs."""
    t0 = ensure_single_text_run(p_elem)
    t0.text = new_text

    # Remove extra runs to avoid leaving old fragments.
    runs = p_elem.findall("hp:run", namespaces=NS)
    for r in runs[1:]:
        p_elem.remove(r)


@dataclass
class UpdateField:
    key: str
    old: str
    new: str


def load_updates() -> dict:
    return json.loads(UPDATE_JSON.read_text(encoding="utf-8"))


def load_followups() -> list[tuple[int, str]]:
    rows = []
    with FOLLOWUPS_CSV.open("r", encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f)
        for r in reader:
            seq_key = None
            for cand in ("sequence", "seq", "order", "idx"):
                if cand in r:
                    seq_key = cand
                    break
            if not seq_key:
                raise ValueError("followups.csv missing sequence column")

            item_key = None
            for cand in ("item", "text", "followup", "내용"):
                if cand in r:
                    item_key = cand
                    break
            if not item_key:
                # fallback: first non-seq column
                for k in r.keys():
                    if k != seq_key:
                        item_key = k
                        break
            if not item_key:
                raise ValueError("followups.csv missing item column")

            rows.append((int(r[seq_key]), (r[item_key] or "").strip()))

    rows.sort(key=lambda x: x[0])
    return rows


def parse_xml(xml_bytes: bytes):
    if ETREE:
        parser = ETREE.XMLParser(remove_blank_text=False, recover=False)
        root = ETREE.fromstring(xml_bytes, parser=parser)
        return root

    import xml.etree.ElementTree as ET

    root = ET.fromstring(xml_bytes)
    return root


def serialize_xml(root) -> bytes:
    if ETREE:
        return ETREE.tostring(root, encoding="UTF-8", xml_declaration=True, pretty_print=False)

    import xml.etree.ElementTree as ET

    return ET.tostring(root, encoding="utf-8", xml_declaration=True)


def infer_old_values_from_doc(xml_roots: dict[str, object], updates: dict) -> list[UpdateField]:
    """Infer old values for known keys by inspecting the document.

    If JSON provides {old,new} objects, use those directly.
    If JSON provides plain new values, derive old values from labelled paragraphs.
    """

    fields: list[UpdateField] = []

    # 1) direct old/new from JSON (if present)
    for k, v in updates.items():
        if isinstance(v, dict) and ("old" in v and "new" in v):
            fields.append(UpdateField(key=k, old=str(v["old"]), new=str(v["new"])) )

    # If we already got explicit mappings for all keys, we're done.
    if fields and all(isinstance(updates.get(f.key), dict) for f in fields):
        return fields

    # 2) infer for known plain-value keys
    # We look across all sections because some values appear in multiple places.

    def find_first_text_matching(pred):
        for _, root in xml_roots.items():
            for p in root.findall(".//hp:p", namespaces=NS):
                txt = paragraph_full_text(p)
                if pred(txt):
                    return txt
        return None

    def find_paragraph_matching(pred):
        for _, root in xml_roots.items():
            for p in root.findall(".//hp:p", namespaces=NS):
                txt = paragraph_full_text(p)
                if pred(txt):
                    return p, txt
        return None, None

    # customer
    if "customer" in updates and not isinstance(updates["customer"], dict):
        p, txt = find_paragraph_matching(lambda t: t.strip().startswith("고객사:"))
        if txt:
            old = txt.split("고객사:", 1)[1].strip()
            fields.append(UpdateField("customer", old=old, new=str(updates["customer"])) )

    # owner
    if "owner_name" in updates and not isinstance(updates["owner_name"], dict):
        p, txt = find_paragraph_matching(lambda t: t.strip().startswith("현 담당자:"))
        if txt:
            old = txt.split("현 담당자:", 1)[1].strip()
            fields.append(UpdateField("owner_name", old=old, new=str(updates["owner_name"])) )

    # renewal window start/end
    if ("window_start" in updates or "window_end" in updates) and (not isinstance(updates.get("window_start"), dict) and not isinstance(updates.get("window_end"), dict)):
        p, txt = find_paragraph_matching(lambda t: "갱신 윈도우:" in t)
        if txt:
            # expected: "갱신 윈도우: YYYY-MM-DD ~ YYYY-MM-DD"
            m = re.search(r"갱신 윈도우:\s*([0-9]{4}-[0-9]{2}-[0-9]{2})\s*~\s*([0-9]{4}-[0-9]{2}-[0-9]{2})", txt)
            if m:
                old_start, old_end = m.group(1), m.group(2)
                if "window_start" in updates:
                    fields.append(UpdateField("window_start", old=old_start, new=str(updates["window_start"])) )
                if "window_end" in updates:
                    fields.append(UpdateField("window_end", old=old_end, new=str(updates["window_end"])) )

    # band
    if "band" in updates and not isinstance(updates["band"], dict):
        # Look for something like "Standard-18M" (document sample).
        old = find_first_text_matching(lambda t: bool(re.fullmatch(r"[A-Za-z]+-[0-9]+M", t.strip())))
        if old:
            fields.append(UpdateField("band", old=old.strip(), new=str(updates["band"])) )

    # escalation email
    if "escalation_email" in updates and not isinstance(updates["escalation_email"], dict):
        old = find_first_text_matching(lambda t: "@" in t and "." in t and " " not in t and len(t) < 120)
        # To reduce false matches, prefer paragraphs that also appear near escalation label.
        p, txt = find_paragraph_matching(lambda t: "@" in t and "northwind" in t)
        if txt:
            old = txt
        if old:
            fields.append(UpdateField("escalation_email", old=old.strip(), new=str(updates["escalation_email"])) )

    # note
    if "note" in updates and not isinstance(updates["note"], dict):
        p, txt = find_paragraph_matching(lambda t: t.strip().startswith("가격 메모:"))
        if txt:
            old = txt.split("가격 메모:", 1)[1].strip()
            fields.append(UpdateField("note", old=old, new=str(updates["note"])) )

    # Deduplicate by (old,new)
    seen = set()
    out = []
    for f in fields:
        k = (f.old, f.new)
        if not f.old:
            continue
        if k in seen:
            continue
        seen.add(k)
        out.append(f)
    return out


def walk_and_replace_text(root, replacements: list[UpdateField]):
    """Replace substring occurrences in .text and .tail across the XML tree.

    Returns:
      - set of modified paragraph elements
    """
    parent_map = build_parent_map(root)
    modified_ps = set()

    def apply_repls(s: str) -> tuple[str, bool]:
        changed = False
        out = s
        for f in replacements:
            if f.old and f.old in out:
                out = out.replace(f.old, f.new)
                changed = True
        return out, changed

    for elem in root.iter():
        if elem.text:
            new_text, ch = apply_repls(elem.text)
            if ch:
                elem.text = new_text
                p = find_ancestor_p(elem, parent_map)
                if p is not None:
                    modified_ps.add(p)
        if getattr(elem, "tail", None):
            new_tail, ch = apply_repls(elem.tail)
            if ch:
                elem.tail = new_tail
                p = find_ancestor_p(elem, parent_map)
                if p is not None:
                    modified_ps.add(p)

    return modified_ps


def update_labelled_paragraphs(root, updates: dict):
    """Rewrite labelled paragraphs to avoid split-run remnants for certain fields.

    Returns:
      - set of modified paragraphs
      - list of inferred old values for those paragraphs
    """
    parent_map = build_parent_map(root)
    modified = set()
    inferred_old = []

    for p in root.findall(".//hp:p", namespaces=NS):
        txt = paragraph_full_text(p)
        t = txt.strip()

        if "customer" in updates and not isinstance(updates["customer"], dict) and t.startswith("고객사:"):
            old = txt.split("고객사:", 1)[1].strip()
            inferred_old.append(("customer", old))
            rewrite_paragraph_text(p, f"고객사: {updates['customer']}")
            modified.add(p)

        if "owner_name" in updates and not isinstance(updates["owner_name"], dict) and t.startswith("현 담당자:"):
            old = txt.split("현 담당자:", 1)[1].strip()
            inferred_old.append(("owner_name", old))
            rewrite_paragraph_text(p, f"현 담당자: {updates['owner_name']}")
            modified.add(p)

        if ("window_start" in updates or "window_end" in updates) and (not isinstance(updates.get("window_start"), dict) and not isinstance(updates.get("window_end"), dict)):
            if "갱신 윈도우:" in txt:
                m = re.search(r"갱신 윈도우:\s*([0-9]{4}-[0-9]{2}-[0-9]{2})\s*~\s*([0-9]{4}-[0-9]{2}-[0-9]{2})", txt)
                if m:
                    old_start, old_end = m.group(1), m.group(2)
                    if "window_start" in updates:
                        inferred_old.append(("window_start", old_start))
                    if "window_end" in updates:
                        inferred_old.append(("window_end", old_end))
                    new_start = updates.get("window_start", old_start)
                    new_end = updates.get("window_end", old_end)
                    rewrite_paragraph_text(p, f"갱신 윈도우: {new_start} ~ {new_end}")
                    modified.add(p)

        if "note" in updates and not isinstance(updates["note"], dict) and t.startswith("가격 메모:"):
            old = txt.split("가격 메모:", 1)[1].strip()
            inferred_old.append(("note", old))
            rewrite_paragraph_text(p, f"가격 메모: {updates['note']}")
            modified.add(p)

        # also update "갱신 윈도우 확인:" occurrences if present (section1 p44)
        if ("window_start" in updates or "window_end" in updates) and "갱신 윈도우 확인:" in txt:
            m = re.search(r"갱신 윈도우 확인:\s*([0-9]{4}-[0-9]{2}-[0-9]{2})\s*~\s*([0-9]{4}-[0-9]{2}-[0-9]{2})", txt)
            if m:
                old_start, old_end = m.group(1), m.group(2)
                if "window_start" in updates:
                    inferred_old.append(("window_start", old_start))
                if "window_end" in updates:
                    inferred_old.append(("window_end", old_end))
                new_start = updates.get("window_start", old_start)
                new_end = updates.get("window_end", old_end)
                rewrite_paragraph_text(p, f"갱신 윈도우 확인: {new_start} ~ {new_end}")
                modified.add(p)

    return modified, inferred_old


def update_followups(root, followups: list[tuple[int, str]]):
    """Replace existing numbered follow-up paragraphs (1., 2., 3., ...) with CSV items.

    Returns:
      - set of modified/created paragraphs
      - list of original follow-up paragraph texts (for printing)
    """
    parent_map = build_parent_map(root)
    modified = set()

    # Find consecutive paragraphs starting at "1.".
    ps = root.findall(".//hp:p", namespaces=NS)
    follow_idx = None
    for i, p in enumerate(ps):
        txt = paragraph_full_text(p).strip()
        if re.match(r"^1\s*\.\s+", txt):
            # require next paragraphs to be 2. and 3. to avoid false match
            if i + 2 < len(ps):
                t2 = paragraph_full_text(ps[i + 1]).strip()
                t3 = paragraph_full_text(ps[i + 2]).strip()
                if re.match(r"^2\s*\.\s+", t2) and re.match(r"^3\s*\.\s+", t3):
                    follow_idx = i
                    break

    if follow_idx is None:
        return modified, []

    # Determine existing run length (1.,2.,3.,...) consecutive.
    existing = []
    j = follow_idx
    while j < len(ps):
        txt = paragraph_full_text(ps[j]).strip()
        m = re.match(r"^(\d+)\s*\.\s+", txt)
        if not m:
            break
        n = int(m.group(1))
        if n != (j - follow_idx + 1):
            break
        existing.append(ps[j])
        j += 1

    orig_texts = [paragraph_full_text(p) for p in existing]

    # Print originals for confirmation (caller prints)

    # Build desired texts
    desired_texts = []
    for idx, (_, item) in enumerate(followups, start=1):
        desired_texts.append(f"{idx}. {item}")

    # Adjust count by adding/removing <hp:p>
    parent = parent_map.get(existing[0])
    if parent is None:
        return modified, orig_texts

    # Find insertion position after last existing follow-up
    last = existing[-1]
    children = list(parent)
    try:
        last_pos = children.index(last)
    except ValueError:
        last_pos = None

    # Create new paragraphs if needed
    if len(desired_texts) > len(existing):
        template = existing[-1]
        # choose new numeric IDs
        existing_ids = []
        for p in root.findall(".//hp:p", namespaces=NS):
            pid = p.get("id")
            if pid and pid.isdigit():
                existing_ids.append(int(pid))
        next_id = (max(existing_ids) + 1) if existing_ids else 1000

        for _ in range(len(desired_texts) - len(existing)):
            newp = copy.deepcopy(template)
            newp.set("id", str(next_id))
            next_id += 1
            insert_at = (last_pos + 1) if last_pos is not None else len(parent)
            parent.insert(insert_at, newp)
            last_pos = insert_at
            existing.append(newp)
            modified.add(newp)

    # Remove extra paragraphs if needed
    if len(desired_texts) < len(existing):
        for p in existing[len(desired_texts):]:
            parent.remove(p)
        existing = existing[: len(desired_texts)]

    # Rewrite texts
    for p, new_txt in zip(existing, desired_texts):
        rewrite_paragraph_text(p, new_txt)
        modified.add(p)

    return modified, orig_texts


def main():
    # Step 3a: copy
    shutil.copyfile(HWPX_IN, HWPX_OUT)

    updates = load_updates()
    followups = load_followups()

    # Read and parse all Contents/*.xml first so we can infer old values.
    with zipfile.ZipFile(HWPX_OUT, "r") as z:
        content_xml_paths = [n for n in z.namelist() if n.startswith("Contents/") and n.lower().endswith(".xml")]
        xml_bytes_by_path = {p: z.read(p) for p in content_xml_paths}

    roots = {p: parse_xml(b) for p, b in xml_bytes_by_path.items()}

    # Build replacements list
    inferred = infer_old_values_from_doc(roots, updates)

    print("\n[INFO] Replacement fields (old -> new):")
    for f in inferred:
        print(f"- {f.key}: '{f.old}' -> '{f.new}'")

    # Apply edits per XML
    modified_paths = []
    old_values_for_verification = []
    new_values_for_verification = []

    with zipfile.ZipFile(HWPX_OUT, "a", compression=zipfile.ZIP_DEFLATED) as z:
        for path, root in roots.items():
            parent_map = build_parent_map(root)
            modified_paragraphs = set()

            # (e) follow-ups replacement (before global replace, so we can print originals)
            fu_modified, fu_originals = update_followups(root, followups)
            if fu_originals:
                print(f"\n[INFO] Existing follow-up paragraphs in {path}:")
                for t in fu_originals:
                    print(f"  - {t}")
            modified_paragraphs |= fu_modified

            # (d) field replacements via substring replace
            modified_paragraphs |= walk_and_replace_text(root, inferred)

            # targeted paragraph rewrites for labelled fields (handles split runs)
            rew_mod, rew_old = update_labelled_paragraphs(root, updates)
            modified_paragraphs |= rew_mod

            # track old/new values for verification checks
            for f in inferred:
                old_values_for_verification.append(f.old)
                new_values_for_verification.append(f.new)
            for _, old in rew_old:
                if old:
                    old_values_for_verification.append(old)
            for k in ("customer", "owner_name", "window_start", "window_end", "band", "escalation_email", "note"):
                v = updates.get(k)
                if v and not isinstance(v, dict):
                    new_values_for_verification.append(str(v))

            # (f) remove layout-cache from modified paragraphs
            # Refresh parent map because we may have inserted/removed nodes.
            parent_map = build_parent_map(root)
            removed_total = 0
            for p in list(modified_paragraphs):
                removed_total += remove_layout_cache_from_paragraph(p, parent_map)

            if modified_paragraphs:
                print(f"\n[INFO] {path}: modified paragraphs={len(modified_paragraphs)}, removed layout-cache elems={removed_total}")

            # (g) Verify appendix sentence exists unchanged
            appendix_ok = False
            for t in root.findall(".//hp:t", namespaces=NS):
                if (t.text or "") == APPENDIX_SENTENCE:
                    appendix_ok = True
                    break
            if not appendix_ok:
                # Attempt to restore: find paragraph containing partial marker and overwrite it.
                for p in root.findall(".//hp:p", namespaces=NS):
                    if "부록 문단" in paragraph_full_text(p):
                        rewrite_paragraph_text(p, APPENDIX_SENTENCE)
                        # remove layout cache just in case
                        parent_map = build_parent_map(root)
                        remove_layout_cache_from_paragraph(p, parent_map)
                        appendix_ok = True
                        break

            print(f"[INFO] Appendix sentence intact in {path}: {appendix_ok}")

            # Write back
            xml_out = serialize_xml(root)
            z.writestr(path, xml_out)
            modified_paths.append(path)

    # Step 4 validation
    print("\n[VALIDATE] Output zip open + checks")
    with zipfile.ZipFile(HWPX_OUT, "r") as z:
        print("ZIP valid, entries:", len(z.namelist()))
        for n in z.namelist():
            print(" -", n)

        for path in modified_paths:
            data = z.read(path)
            text = data.decode("utf-8", "replace")
            print(f"\n===== {path} (modified) =====")
            print(text)

            # old values should be gone
            for old in sorted(set(old_values_for_verification)):
                if not old:
                    continue
                if old in text:
                    print(f"[WARN] Old value still present in {path}: {old!r}")

            # new values should be present (at least one appearance somewhere)
            for newv in sorted(set(new_values_for_verification)):
                if not newv:
                    continue
                if newv not in text:
                    # not every new value appears in every section; report but don't fail hard.
                    pass

            # follow-up lines should match
            for idx, (_, item) in enumerate(followups, start=1):
                expected = f"{idx}. {item}"
                if expected not in text:
                    print(f"[WARN] Missing follow-up line in {path}: {expected!r}")

            # appendix sentence should exist
            if APPENDIX_SENTENCE not in text:
                print(f"[ERROR] Appendix sentence missing in {path}")

            # no layout-cache tags in modified paragraphs: best-effort check across whole file
            if re.search(r"<hp:(?:lineSegArray|lineSeg|linesegarray|lineseg)\b", text, re.IGNORECASE):
                print(f"[WARN] Layout-cache elements still present in {path}")


if __name__ == "__main__":
    main()

