into the ZIP.", "+    # Rebuild the zip at the same output path to avoid duplicate entries.", "+    with zipfile.ZipFile(HWPX_OUT, "w", compression=zipfile.ZIP_DEFLATED) as z:", "+        for name, data in entries.items():", "+            if name in modified_xml_bytes:", "+                z.writestr(name, modified_xml_bytes[name])", "+            else:", "+                z.writestr(name, data)", " ", "-    # Step 4 validation", "-    print("\n[VALIDATE] Output zip open + checks")", "+    # 4. Validate the output", "+    print("\n[VALIDATE] Open output zip and verify content")", "     with zipfile.ZipFile(HWPX_OUT, "r") as z:", "         print("ZIP valid, entries:", len(z.namelist()))", "         for n in z.namelist():", "             print(" -", n)", " ", "-        for path in modified_paths:", "-            data = z.read(path)", "-            text = data.decode("utf-8", "replace")", "+        for path in sorted(modified_xml_bytes.keys()):", "+            xml = z.read(path).decode("utf-8", "replace")", "             print(f"\n===== {path} (modified) =====")", "-            print(text)", "+            print(xml)", " ", "-            # old values should be gone", "-            for old in sorted(set(old_values_for_verification)):", "-                if not old:", "-                    continue", "-                if old in text:", "-                    print(f"[WARN] Old value still present in {path}: {old!r}")", "+            # Old values should be gone from this file", "+            for old in old_values:", "+                if old in xml:", "+                    print(f"[ERROR] Old value still present in {path}: {old!r}")", " ", "-            # new values should be present (at least one appearance somewhere)", "-            for newv in sorted(set(new_values_for_verification)):", "-                if not newv:", "-                    continue", "-                if newv not in text:", "-                    # not every new value appears in every section; report but d